SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS collection_sites (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  display_order TINYINT UNSIGNED NOT NULL,
  name VARCHAR(160) NOT NULL,
  ward VARCHAR(20) NOT NULL,
  address VARCHAR(180) NOT NULL,
  hours_text VARCHAR(180) NOT NULL,
  latitude DECIMAL(10, 7) NOT NULL,
  longitude DECIMAL(10, 7) NOT NULL,
  source_url VARCHAR(500) NOT NULL,
  source_checked_at DATE NOT NULL,
  coordinate_source_url VARCHAR(500) NOT NULL,
  coordinate_checked_at DATE NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY collection_sites_display_order_unique (display_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

